<script setup>
import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {useAdminAuthStore} from '../stores/adminAuth.js';import {changeStorefrontStatus,fetchPlatformStore} from '../services/adminSession.js'
const auth=useAdminAuthStore(),route=useRoute(),store=ref(null),error=ref(''),busy=ref(false);const labels={shopify_connection:'Shopify bağlantısı',plan_selection:'Plan seçimi',niche_selection:'Niche seçimi',banner_selection:'Banner seçimi',brand_setup:'Marka ayarları',product_readiness:'Ürün hazırlığı',store_preview:'Mağaza önizleme',domain_setup:'Domain',publish:'Yayınlama'}
const date=v=>v?new Intl.DateTimeFormat('tr-TR',{dateStyle:'medium'}).format(new Date(v)):'—';async function load(){store.value=await fetchPlatformStore({apiUrl:import.meta.env.VITE_API_URL||'',accessToken:auth.session.access_token,storeId:route.params.storeId})}
async function changeStatus(){const status=store.value.storefront.status==='suspended'?'active':'suspended',reason=window.prompt('İşlem gerekçesi (en az 10 karakter):');if(!reason)return;const confirmation=window.prompt(`Onaylamak için mağaza adını aynen yazın: ${store.value.name}`);if(!confirmation)return;busy.value=true;error.value='';try{await changeStorefrontStatus({apiUrl:import.meta.env.VITE_API_URL||'',accessToken:auth.session.access_token,storeId:store.value.id,status,reason,confirmation});await load()}catch(e){error.value=e.message}finally{busy.value=false}}onMounted(()=>load().catch(()=>error.value='Mağaza detayı yüklenemedi.'))
</script>
<template><main class="dashboard"><header><div><div class="eyebrow">MAĞAZA DETAYI</div><h1>{{store?.name||'Yükleniyor…'}}</h1></div><RouterLink class="button-link secondary" to="/stores">Mağazalara dön</RouterLink></header><p v-if="error" class="notice">{{error}}</p><template v-if="store"><section class="panel"><dl><div><dt>Shopify domaini</dt><dd>{{store.myshopifyDomain}}</dd></div><div><dt>Durum</dt><dd>{{store.status}} · {{store.storefront?.status||'yok'}}</dd></div><div><dt>Workspace</dt><dd>{{store.workspace.name}}</dd></div><div><dt>Abonelik</dt><dd>{{store.subscription?.status||'yok'}}</dd></div><div><dt>Plan</dt><dd>{{store.subscription?.planKey||'—'}}</dd></div><div><dt>Dönem sonu</dt><dd>{{date(store.subscription?.currentPeriodEnd)}}</dd></div></dl><button v-if="store.storefront&&['owner','admin'].includes(auth.admin?.role)" class="secondary" :disabled="busy" @click="changeStatus">{{store.storefront.status==='suspended'?'Storefront’u yeniden etkinleştir':'Storefront’u askıya al'}}</button></section><h2>Kurulum adımları</h2><section class="metrics"><article v-for="step in store.onboarding" :key="step.key"><span>{{labels[step.key]||step.key}}</span><strong class="step-status">{{step.status}}</strong><small>{{date(step.updatedAt)}}</small></article></section></template></main></template>
